import ast
from pathlib import Path

root = Path("sandbox")
root.mkdir()
files = {
    "model": "",
    "store": "import model\n",
    "report": "import store\n",
    "ui": "import model\nimport store\n",
}
# one bad edge: the bottom layer reaches up for a display helper
files["model"] = "import ui\n"
for name, body in files.items():
    (root / f"{name}.py").write_text(body)

LAYERS = {"model": 0, "store": 1, "report": 1, "ui": 2}
graph = {}
for name in files:
    tree = ast.parse((root / f"{name}.py").read_text())
    deps = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            deps.update(a.name for a in node.names if a.name in files)
        elif isinstance(node, ast.ImportFrom) and node.module in files:
            deps.add(node.module)
    graph[name] = sorted(deps)

print("adjacency:")
for name in sorted(graph):
    deps = ", ".join(graph[name]) if graph[name] else "(nothing)"
    print(f"  {name} -> {deps}")
print("wrong-direction edges:")
for name in sorted(graph):
    for dep in graph[name]:
        if LAYERS[dep] > LAYERS[name]:
            print(f"  {name} (layer {LAYERS[name]}) imports {dep} (layer {LAYERS[dep]})")

